callGraph.callee:
items.map(row => {
    const dt = String(row[0] || '')
    const factor = adjMap.get(dt) || latestFactor
    const ratio = factor / latestFactor
    return {
      date: dt.replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3'),
      open: Number(row[1] || 0) * ratio, high: Number(row[2] || 0) * ratio,
      low: Number(row[3] || 0) * ratio, close: Number(row[4] || 0) * ratio,
      volume: Number(row[5] || 0),
    }
  }).filter

fetch(`/api/news-events?${query}`, { signal: controller.signal })
      .then(async (response) => {
        const payload = await response.json() as { events?: NewsChartEvent[] }
        if (!response.ok) throw new Error('news_overlay_failed')
        setState({ events: Array.isArray(payload.events) ? payload.events : [], status: 'ready' })
      })
      .catch

Promise.all([loadLLMConfig(userId), getUserDataKeys(userId)])
      .then(([config, dataKeys]) => {
        setHasModelConfig(Boolean(config?.api_key && config.model))
        setHasDataKeys(Boolean(dataKeys.tickflow || dataKeys.tushare))
      })
